   function SetProxy()
   {
   section_insert()
      section_start("\u007b\u0022n\u0022:\u0022Получаем параметр функции\u0022,\u0022c\u0022:\u00222\u0022\u007d", 45472996)!
      /*Dat:eyJzIjoiZ2V0ZnVuY3Rpb25wYXJhbWV0ZXIiLCJ2IjoxLCJmIjpbXSwidXciOiIwIiwidXQiOiIwIiwidXRvIjoiMCIsInVtIjoiMCIsImQiOlt7ImlkIjoiUGFyYW1ldGVyTmFtZSIsInR5cGUiOiJjb25zdHIiLCJkYXRhIjoiSnNvbkRhdGEiLCJjbGFzcyI6InN0cmluZyJ9LHsiaWQiOiJTYXZlIiwidHlwZSI6InZhciIsImRhdGEiOiJKU09OREFUQSJ9XX0=*/
      VAR_JSONDATA = _function_argument("JsonData")
      section_end()!

      section_start("", 595634593)!
      /*Dat:*/
      try {
      VAR_PROXYIP = JPath.value(VAR_JSONDATA, ".Proxy.Ip");
      } catch (e) {
      fail(e);
      }
      section_end()!

      section_start("", 575167609)!
      /*Dat:*/
      try {
      VAR_PROXYPORT = JPath.value(VAR_JSONDATA, ".Proxy.Port");
      } catch (e) {
      fail(e);
      }
      section_end()!

      section_start("", 79981769)!
      /*Dat:*/
      try {
      VAR_PROXYLOGIN = JPath.value(VAR_JSONDATA, ".Proxy.Login");
      } catch (e) {
      fail(e);
      }
      section_end()!

      section_start("", 970287809)!
      /*Dat:*/
      try {
      VAR_PROXYPASSWORD = JPath.value(VAR_JSONDATA, ".Proxy.Password");
      } catch (e) {
      fail(e);
      }
      section_end()!

      section_start("", 252211979)!
      /*Dat:*/
      /*Browser*/
      var hash = proxy_parse(VAR_PROXYIP + ":" + VAR_PROXYPORT)
      if("http" != "auto" ){
      hash["IsHttp"] = "http" == "http"
      }
      var login = VAR_PROXYLOGIN
      var password = VAR_PROXYPASSWORD
      if(login.length > 0 && password.length > 0 )
      {
      hash["name"] = login
      hash["password"] = password
      }
      if(_get_profile().length > 0)
      {
      if(hash["server"].length == 0)
      {
      native("filesystem", "removefile", _get_profile() + "/proxy.txt")
      }else
      {
      var PortNumber = hash["Port"]
      hash["Port"] = hash["Port"].toString()
      native("filesystem", "writefile", JSON.stringify({path: _get_profile() + "/proxy.txt",value: JSON.stringify(hash),base64:false,append:false}))
      hash["Port"] = PortNumber
      }
      }
      set_proxy(hash["server"], hash["Port"], hash["IsHttp"], hash["name"], hash["password"])!
      sleep(1000)!
      set_proxy_extended("true" == "true", "true" == "true", "true" == "true", "true" == "true", "true" == "true", "database", "", null)!
      sleep(1000)!
      section_end()!

   }
   section_end()!

